      "plain": "Advantage+ audience automation ব্যবহার করে সম্ভাব্য ফল খোঁজে। Control delivery-এর সীমা নির্ধারণ করে; suggestion দিকনির্দেশ দেয়, তার বাইরেও eligible মানুষকে reach করা হতে পারে। একই field-এর আচরণ campaign ও current option অনুযায়ী বদলাতে পারে। “Use as a suggestion” বা সমজাতীয় label পড়ুন, saved settings রাখুন। Included Custom Audience-কে suggestion করলে সেটি শুধু ওই group-এর retargeting-এর নিশ্চয়তা নয়। Current help page এই review-তে login-blocked ছিল; তাই সবার জন্য স্থির control list বা click path শেখানো হচ্ছে না।",
