      "plain": "Retargeting এমন মানুষকে reach করে যাঁরা আগেই interested হতে পারেন। তাই attributed sales সবই ad-এর কারণে অতিরিক্ত এসেছে বলা যায় না। A/B comparison strategy choice পরীক্ষা করে; no-ad holdout-সহ উপযুক্ত lift design বিজ্ঞাপনের incremental impact প্রশ্ন করে। Random assignment, comparable groups, observation window, cross-exposure এবং statistical uncertainty দরকার। এই lesson-এর ছোট হিসাব teaching example, powered study বা causal proof নয়।",
