      "plain": "A/B test তুলনাযোগ্য groups-এ treatment-এর ফল তুলতে সাহায্য করে। একটি creative hypothesis পরীক্ষা করলে budget/offer-এর অপ্রয়োজনীয় অন্য পরিবর্তন কমান। Available Experiments/A/B workflow-এর eligibility, split, metric, duration ও budget requirements current setup অনুযায়ী যাচাই করুন; minimum সংখ্যা বানিয়ে ব্যবহার নয়। শুরুতেই primary metric, practical improvement threshold, guardrails এবং stopping plan লিখুন। Early good result দেখে বারবার stop/restart করলে interpretation দুর্বল হয়। Test report-এর uncertainty/confidence এবং volume দেখুন; inconclusive মানে ফল সমান প্রমাণ নয়। Brand lift সাধারণত survey-based brand outcome-এর difference দেখে, যেমন awareness; sales lift একই metric নয়। Conversion lift treatment বনাম উপযুক্ত control/holdout দিয়ে অতিরিক্ত outcome-এর প্রশ্ন তোলে। দুটি চালু ad-এর observational CPA comparison নিজে থেকে randomized A/B বা lift study নয়। যথেষ্ট budget/eligibility না থাকলে honest learning plan করুন, causal proof দাবি নয়।",
      "analogy": "একই ধরনের দুই জমিতে শুধু একটি সার বদলে ফল তুললে প্রশ্ন পরিষ্কার থাকে। মাটি, পানি, ফসল সব বদলালে কোন কারণে ফল বদলেছে বোঝা কঠিন।",
      "terms": "Treatment = পরিবর্তিত অভিজ্ঞতা; Control = তুলনার baseline; Primary metric = আগের সিদ্ধান্তের মাপ; Inconclusive = পর্যাপ্ত নিশ্চিত সিদ্ধান্ত নেই; Brand lift = survey-based brand outcome difference।",
      "steps": [
        "একটি hypothesis এবং expected business relevance লিখুন।",
        "Primary metric, threshold, guardrails ও stopping rule predeclare করুন।",
        "Eligible A/B setup-এ split, variable, duration ও budget যাচাই করুন।",
        "Tracking consistency, overlap এবং external changes review করুন।",
        "Report-এ effect, uncertainty ও conclusive/inconclusive status পড়ুন।",
        "Adopt, iterate বা retest সিদ্ধান্ত দিন; brand/conversion lift scope আলাদা রাখুন।"
      ],
