      "goal": "একটি demo ad-এর creative-to-destination review checklist ও status response plan লিখবেন।",
      "plain": "Ad review বিজ্ঞাপনের policy যাচাইয়ের প্রক্রিয়া; approval মানে business-এর সব দাবি, product বা legal eligibility certify করা নয়। Text, visuals ও destination-এর consistency নিয়ে একটি preflight করুন। Ads Manager-এর delivery status এবং applicable Business Support Home-এ stated issue দেখুন; pending, rejected এবং account-level restriction আলাদা সমস্যা। Automated ও further review থাকতে পারে, কিন্তু প্রতিটি trigger বা human-review timing আমরা জানি ধরে নেবেন না। এই source review-এ “MARS” নামের universal system ও সব review ৬০ seconds-এর মধ্যে হওয়ার official প্রমাণ পাওয়া যায়নি; এটি curriculum fact নয়। Launch plan-এ review delay-এর সুযোগ রাখুন। Approved ad-এ পরে issue দেখা গেলে status/notice অনুযায়ী পুনরায় review হতে পারে; পুরোনো approval ভবিষ্যতের guarantee নয়। কারণ জানা গেলে actual issue সংশোধন করুন। ভুল সিদ্ধান্ত মনে হলে available review channel ব্যবহার করুন; reviewer-এর কাছে এক content আর user-এর কাছে অন্য content দেখানো সমাধান নয়।",
      "analogy": "একটি দোকানের বিজ্ঞাপন পড়ার সঙ্গে মানুষ দোকানে গিয়ে কী পাবেন তা মিলতে হবে। পোস্টার অনুমোদন দোকানের সব কাজের certificate নয়।",
      "terms": "Review = policy evaluation; Delivery status = চলার অবস্থা; Rejection = ad-level decision; Restriction = asset/account-level সীমা; Preflight = প্রকাশের আগে যাচাই।",
      "steps": [
        "Offer, evidence, text, visuals ও destination একসঙ্গে review করুন।",
        "Applicable policy ও current account requirements নথিভুক্ত করুন।",
        "Launch timeline-এ review contingency রাখুন।",
        "Delivery status ও affected asset/notice স্পষ্ট পড়ুন।",
        "Actual issue edit করুন অথবা available review path-এ evidence দিন।",
        "Status outcome, version ও পরের action log করুন।"
      ],
      "example": "Demo “ঢাকা ডেস্ক” ad-এ price ৳৩,০০০, landing-এ ৳৩,৫০০ এবং hidden delivery charge। Preflight-এ inconsistency ধরুন; status rejected হলে stated reason পড়ুন। শুধু spelling বদলালে price mismatch ঠিক হয় না। Planned launch date review completion-এর guarantee নয়।",
      "trap": "Approval-কে legal/claim certificate বা নাম না-যাচাই করা review system-এর speed promise বলা।",
      "task": "Demo ad preflight তৈরি করুন: copy, image, landing, price/fees, status, version এবং pending/rejected/restricted তিন action path।",
