      "plain": "Value optimization available হলে reported conversion value-এর জন্য delivery optimize করার controls থাকতে পারে। Exact performance goal, bid strategy ও eligibility নিজের current account-এ verify করুন। Purchase value সাধারণত recorded sales value; সেটি net profit নয়। Profit বুঝতে net realized revenue থেকে product cost, variable fulfillment/payment cost, discounts/refunds-এর consistent accounting এবং ad spend বাদ দিতে হবে। একই revenue ROAS-এ দুই product mix-এর margin ভিন্ন হতে পারে। Contribution before ads ÷ net realized revenue হলো এই lesson-এর defined contribution rate; শুধু একই cost scope ও window-তে break-even ROAS = 1 ÷ rate হিসাব করুন। Fixed overhead এখানে নেই, তাই এটি net-profit threshold নয়। Zero/negative contribution-এ reciprocal target দিয়ে লাভ উদ্ধার হয় না। Value/currency truth বদলে fake margin values পাঠাবেন না; supported documented value tools ছাড়া event semantics গুলিয়ে নয়। Margin segments, accurate inventory ও measured business KPIs দিয়ে test করুন।",
