      "plain": "Seasonal campaign শুধু budget বাড়ানো নয়; offer, inventory, creative, checkout, delivery ও service capacity একসঙ্গে প্রস্তুত করা। Eid dates অঞ্চল/calendar announcement অনুযায়ী যাচাই করুন; প্রতি বছর একই Gregorian date নয়। Black Friday-এর calendar ও local relevance verify করুন; বিদেশি discount claim নিজের offer-এর সত্যতা প্রমাণ করে না। Launch-এর আগে previous comparable period ও current unit economics দেখুন, তবে historical demand guarantee নয়। Preview truthful price/discount terms এবং delivery cut-off দিন। আগে checkout/events/load handling test করুন। Budget changes hypothesis ও risk scope অনুযায়ী ধাপে review করুন; fixed ২০% বা double-every-day universal rule নেই। Sold-out items, delayed dispatch, returns এবং marginal outcome monitor করুন। Ad report delay-এর সময়ে business order log কাজে লাগে। Peak শেষে backlog, refunds ও realized contribution reconcile করুন এবং next-season learnings লিখুন।",
      "analogy": "ঈদের আগে দোকানের ভিড় বাড়লে শুধু মাইক জোরে নয়—stock, cashier ও deliveryও প্রস্তুত লাগে।",
      "terms": "Cut-off = শেষ গ্রহণ/ডেলিভারি সময়; Capacity = fulfill করার সীমা; Guardrail = stop/review condition; Reconcile = হিসাব মিলানো।",
